1	package stats
2	
3	import "sort"
4	
5	// Mean returns the arithmetic mean of xs, or 0 for an empty slice.
6	func Mean(xs []float64) float64 {
7		if len(xs) == 0 {
8			return 0
9		}
10		var s float64
11		for _, x := range xs {
12			s += x
13		}
14		return s / float64(len(xs))
15	}
16	
17	// Median returns the middle value of xs.
18	func Median(xs []float64) float64 {
19		if len(xs) == 0 {
20			return 0
21		}
22		c := append([]float64(nil), xs...)
23		sort.Float64s(c)
24		n := len(c)
25		if n%2 == 1 {
26			return c[n/2]
27		}
28		return (c[n/2-1] + c[n/2]) / 2
29	}
30	
31	// Max returns the largest value of xs.
32	func Max(xs []float64) float64 {
33		m := xs[0]
34		for _, x := range xs {
35			if x > m {
36				m = x
37			}
38		}
39		return m
40	}
